create extension if not exists pgcrypto;
create table public.sf_projects (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null check (char_length(name) between 1 and 80), slug text not null, website_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id,slug));
create table public.sf_schemas (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.sf_projects(id) on delete cascade, name text not null check (name ~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$'), created_at timestamptz not null default now(), unique(project_id,name));
create table public.sf_tables (id uuid primary key default gen_random_uuid(), schema_id uuid not null references public.sf_schemas(id) on delete cascade, name text not null check (name ~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$'), created_at timestamptz not null default now(), unique(schema_id,name));
create table public.sf_columns (id uuid primary key default gen_random_uuid(), table_id uuid not null references public.sf_tables(id) on delete cascade, name text not null check (name ~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$'), data_type text not null default 'text' check (data_type in ('text','number','boolean','json','date')), is_primary_key boolean not null default false, ordinal integer not null default 0 check (ordinal >= 0), created_at timestamptz not null default now(), unique(table_id,name));
create table public.sf_rows (id uuid primary key default gen_random_uuid(), table_id uuid not null references public.sf_tables(id) on delete cascade, data jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object'), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index sf_projects_owner_idx on public.sf_projects(owner_id);
create index sf_schemas_project_idx on public.sf_schemas(project_id);
create index sf_tables_schema_idx on public.sf_tables(schema_id);
create index sf_columns_table_idx on public.sf_columns(table_id);
create index sf_rows_table_idx on public.sf_rows(table_id);
create index sf_rows_data_idx on public.sf_rows using gin(data);
create or replace function public.sf_enforce_project_limit() returns trigger language plpgsql security invoker set search_path = '' as $$
declare project_count integer;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(new.owner_id::text, 0));
  select count(*) into project_count from public.sf_projects where owner_id = new.owner_id;
  if project_count >= 10 then raise exception 'Project limit reached: each account can create up to 10 projects.' using errcode = '23514'; end if;
  return new;
end; $$;
create trigger sf_projects_limit_before_insert before insert on public.sf_projects for each row execute function public.sf_enforce_project_limit();
create or replace function public.sf_touch_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at = now(); return new; end; $$;
create trigger sf_projects_touch_updated_at before update on public.sf_projects for each row execute function public.sf_touch_updated_at();
create trigger sf_rows_touch_updated_at before update on public.sf_rows for each row execute function public.sf_touch_updated_at();
alter table public.sf_projects enable row level security;
alter table public.sf_schemas enable row level security;
alter table public.sf_tables enable row level security;
alter table public.sf_columns enable row level security;
alter table public.sf_rows enable row level security;
create policy "Owners manage their projects" on public.sf_projects for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy "Owners manage project schemas" on public.sf_schemas for all to authenticated using (exists (select 1 from public.sf_projects p where p.id = project_id and p.owner_id = (select auth.uid()))) with check (exists (select 1 from public.sf_projects p where p.id = project_id and p.owner_id = (select auth.uid())));
create policy "Owners manage schema tables" on public.sf_tables for all to authenticated using (exists (select 1 from public.sf_schemas s join public.sf_projects p on p.id = s.project_id where s.id = schema_id and p.owner_id = (select auth.uid()))) with check (exists (select 1 from public.sf_schemas s join public.sf_projects p on p.id = s.project_id where s.id = schema_id and p.owner_id = (select auth.uid())));
create policy "Owners manage table columns" on public.sf_columns for all to authenticated using (exists (select 1 from public.sf_tables t join public.sf_schemas s on s.id = t.schema_id join public.sf_projects p on p.id = s.project_id where t.id = table_id and p.owner_id = (select auth.uid()))) with check (exists (select 1 from public.sf_tables t join public.sf_schemas s on s.id = t.schema_id join public.sf_projects p on p.id = s.project_id where t.id = table_id and p.owner_id = (select auth.uid())));
create policy "Owners manage table rows" on public.sf_rows for all to authenticated using (exists (select 1 from public.sf_tables t join public.sf_schemas s on s.id = t.schema_id join public.sf_projects p on p.id = s.project_id where t.id = table_id and p.owner_id = (select auth.uid()))) with check (exists (select 1 from public.sf_tables t join public.sf_schemas s on s.id = t.schema_id join public.sf_projects p on p.id = s.project_id where t.id = table_id and p.owner_id = (select auth.uid())));
grant select, insert, update, delete on public.sf_projects to authenticated;
grant select, insert, update, delete on public.sf_schemas to authenticated;
grant select, insert, update, delete on public.sf_tables to authenticated;
grant select, insert, update, delete on public.sf_columns to authenticated;
grant select, insert, update, delete on public.sf_rows to authenticated;
